#[cfg(any(target_os = "linux", target_os = "macos", test))]
#[derive(Default)]
struct WorldDispatchConcurrencyTracker {
    ephemeral_by_session: BTreeMap<String, usize>,
    retained_bootstrap_by_session: BTreeMap<String, usize>,
}

#[cfg(any(target_os = "linux", target_os = "macos", test))]
#[derive(Clone, Copy, Debug)]
enum WorldDispatchConcurrencyKind {
    Ephemeral,
    RetainedBootstrap,
}

#[cfg(any(target_os = "linux", target_os = "macos", test))]
#[derive(Debug)]
struct WorldDispatchConcurrencyGuard {
    session_id: String,
    kind: WorldDispatchConcurrencyKind,
}

#[cfg(target_os = "linux")]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ContinueWorldWorkerTurnKind {
    GenericContinue,
    ApprovalResponse,
    ClarificationResponse,
    ProgressAck,
    ControlDirective,
}

#[cfg(any(target_os = "linux", target_os = "macos", test))]
impl Drop for WorldDispatchConcurrencyGuard {
    fn drop(&mut self) {
        let mut tracker = world_dispatch_concurrency_tracker()
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let counts = match self.kind {
            WorldDispatchConcurrencyKind::Ephemeral => &mut tracker.ephemeral_by_session,
            WorldDispatchConcurrencyKind::RetainedBootstrap => {
                &mut tracker.retained_bootstrap_by_session
            }
        };
        match counts.get_mut(&self.session_id) {
            Some(count) if *count > 1 => *count -= 1,
            Some(_) => {
                counts.remove(&self.session_id);
            }
            None => {}
        }
    }
}

#[cfg(any(target_os = "linux", target_os = "macos", test))]
fn world_dispatch_concurrency_tracker() -> &'static Mutex<WorldDispatchConcurrencyTracker> {
    static TRACKER: LazyLock<Mutex<WorldDispatchConcurrencyTracker>> =
        LazyLock::new(|| Mutex::new(WorldDispatchConcurrencyTracker::default()));
    &TRACKER
}

#[cfg(target_os = "linux")]
const ACTIVE_EPHEMERAL_CANCEL_TERMINAL_WAIT_TIMEOUT: Duration = Duration::from_secs(5);

#[cfg(target_os = "linux")]
async fn wait_for_supervised_ephemeral_terminal_truth(
    execution_supervisor: &WorldWorkExecutionSupervisor,
    acceptance_record_id: &str,
    orchestration_session_id: &str,
    task_run_id: &str,
) -> Result<WorldTaskTerminalStateV1> {
    let deadline = Instant::now() + ACTIVE_EPHEMERAL_CANCEL_TERMINAL_WAIT_TIMEOUT;
    loop {
        let observation = execution_supervisor
            .inspect_observation_by_acceptance_id(acceptance_record_id)?
            .ok_or_else(|| {
                anyhow::anyhow!(
                    "cancel_closeout_tracking_lost: active ephemeral task {} in orchestration session {} lost its exact supervisor claim",
                    task_run_id,
                    orchestration_session_id
                )
            })?;
        if let Some(terminal) = observation.terminal {
            return Ok(world_task_terminal_state_from_exit_code(terminal.exit_code));
        }
        if Instant::now() >= deadline {
            anyhow::bail!(
                "cancel_closeout_timeout: active ephemeral task {} in orchestration session {} did not surface exact durable terminal truth after execute cancel delivery",
                task_run_id,
                orchestration_session_id
            );
        }
        tokio::time::sleep(Duration::from_millis(25)).await;
    }
}

#[cfg(target_os = "linux")]
fn active_ephemeral_terminal_state_label(state: WorldTaskTerminalStateV1) -> &'static str {
    match state {
        WorldTaskTerminalStateV1::Completed => "completed",
        WorldTaskTerminalStateV1::Failed => "failed",
        WorldTaskTerminalStateV1::Cancelled => "cancelled",
        WorldTaskTerminalStateV1::NeedsRetainedFollowup => "needs_retained_followup",
    }
}

#[cfg(target_os = "linux")]
fn connect_world_agent_client() -> Result<transport_api_client::AgentClient> {
    let socket_path = std::env::var_os("SUBSTRATE_WORLD_SOCKET")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("/run/substrate.sock"));
    transport_api_client::AgentClient::unix_socket(&socket_path).map_err(|err| {
        anyhow::anyhow!("failed to connect world transport for execute cancel: {err}")
    })
}

#[allow(dead_code)]
pub(crate) fn prepare_orchestrator_world_dispatch(
    store: &AgentRuntimeStateStore,
    request: WorldDispatchRequestV1,
) -> Result<PreparedOrchestratorWorldDispatch> {
    let request = request.validate()?;
    #[cfg(any(target_os = "linux", target_os = "macos", test))]
    if request.action == WorldDispatchActionV1::RunWorldTask
        || (request.action == WorldDispatchActionV1::ContinueWorldWorker
            && !matches!(
                request.payload,
                WorldDispatchPayloadV1::WorkerContinueForkCommand(_)
            ))
        || ((request.action == WorldDispatchActionV1::InspectWorldWorker
            || request.action == WorldDispatchActionV1::CancelWorldWork)
            && request.mode == WorldDispatchModeV1::Ephemeral)
    {
        let retained_target = if request.action == WorldDispatchActionV1::ContinueWorldWorker {
            Some((
                request
                    .target_participant_id
                    .as_deref()
                    .expect("validated continue request includes target participant"),
                request.target_backend_id.as_str(),
            ))
        } else {
            None
        };
        let authority = store
            .resolve_world_work_registry_authority(
                &request.orchestration_session_id,
                &request.caller_participant_id,
                &request.world_id,
                request.world_generation,
                retained_target,
            )
            .map_err(map_world_dispatch_resolution_error)?;
        return Ok(PreparedOrchestratorWorldDispatch {
            store: store.clone(),
            request,
            b_owned_authority: Some(authority),
            compatibility: None,
        });
    }
    let authority = store
        .resolve_internal_world_dispatch_caller(
            &request.orchestration_session_id,
            &request.caller_participant_id,
        )
        .map_err(map_world_dispatch_resolution_error)?;
    let session = authority.session;
    let caller_participant = authority.caller_participant;
    let live_retained_worker_count = store.count_authoritative_live_retained_workers(
        &session.orchestration_session_id,
        caller_participant.participant_id(),
    )?;

    Ok(PreparedOrchestratorWorldDispatch {
        store: store.clone(),
        request,
        #[cfg(any(target_os = "linux", target_os = "macos", test))]
        b_owned_authority: None,
        compatibility: Some(CompatibilityPreparedOrchestratorWorldDispatch {
            session,
            caller_participant,
            target_participant: None,
            live_retained_worker_count,
        }),
    })
}

#[allow(dead_code)]
pub(crate) async fn dispatch_orchestrator_world_request(
    store: &AgentRuntimeStateStore,
    request: WorldDispatchRequestV1,
) -> Result<WorldDispatchOutcomeV1> {
    #[cfg(target_os = "linux")]
    if request.action == WorldDispatchActionV1::SpawnWorldWorker {
        let request = request.validate()?;
        return spawn_prepared_world_worker(
            prepare_authority_bound_spawn_world_worker(request)?,
            None,
        )
        .await;
    }
    let prepared = prepare_orchestrator_world_dispatch(store, request)?;
    dispatch_prepared_orchestrator_world_request(prepared).await
}

