#[cfg(target_os = "linux")]
fn continue_world_worker_event_payload(
    event: &substrate_common::agent_events::AgentEvent,
) -> serde_json::Value {
    let mut payload = None;
    for pointer in [
        "/payload",
        "/uaa_event/payload",
        "/uaa_event/raw_event/payload",
        "/raw_event/payload",
    ] {
        if let Some(candidate) = event.data.pointer(pointer) {
            payload = Some(candidate.clone());
            break;
        }
    }
    let mut payload = payload.unwrap_or_else(|| event.data.clone());

    let payload_missing_event_id =
        continue_world_worker_string_field(&payload, &["/event_id"]).is_none();
    let payload_missing_message_id =
        continue_world_worker_string_field(&payload, &["/message_id"]).is_none();
    if let Some(object) = payload.as_object_mut() {
        if payload_missing_event_id {
            if let Some(event_id) = continue_world_worker_string_field(
                &event.data,
                &[
                    "/event_id",
                    "/uaa_event/event_id",
                    "/uaa_event/raw_event/event_id",
                    "/raw_event/event_id",
                ],
            ) {
                object.insert(
                    "event_id".to_string(),
                    serde_json::Value::String(event_id.to_string()),
                );
            }
        }
        if payload_missing_message_id {
            if let Some(message_id) = continue_world_worker_string_field(
                &event.data,
                &[
                    "/message_id",
                    "/uaa_event/message_id",
                    "/uaa_event/raw_event/message_id",
                    "/raw_event/message_id",
                ],
            ) {
                object.insert(
                    "message_id".to_string(),
                    serde_json::Value::String(message_id.to_string()),
                );
            }
        }
    }

    payload
}

#[cfg(target_os = "linux")]
fn continue_world_worker_string_field<'a>(
    data: &'a serde_json::Value,
    pointers: &[&str],
) -> Option<&'a str> {
    pointers.iter().find_map(|pointer| {
        data.pointer(pointer)
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
    })
}

#[cfg(target_os = "linux")]
fn continue_world_worker_bool_field(data: &serde_json::Value, pointers: &[&str]) -> Option<bool> {
    pointers
        .iter()
        .find_map(|pointer| data.pointer(pointer).and_then(serde_json::Value::as_bool))
}

#[cfg(target_os = "linux")]
fn continue_world_worker_identity_field(value: Option<&str>) -> Option<&str> {
    value.map(str::trim).filter(|value| !value.is_empty())
}

#[cfg(target_os = "linux")]
fn receipt_from_registered_event(
    event: substrate_common::agent_events::AgentEvent,
    transport_request: &MemberDispatchTransportRequest,
    dispatch_request: &ValidatedWorldDispatchRequestV1,
    launch_span_id: String,
) -> Result<SpawnWorldWorkerReceipt> {
    let participant_id = event.participant_id.ok_or_else(|| {
        anyhow::anyhow!(
            "protocol error: spawn_world_worker registered event omitted participant_id"
        )
    })?;
    if participant_id != transport_request.participant_id {
        anyhow::bail!(
            "protocol error: spawn_world_worker registered participant_id {} did not match requested {}",
            participant_id,
            transport_request.participant_id,
        );
    }

    let backend_id = event.backend_id.ok_or_else(|| {
        anyhow::anyhow!("protocol error: spawn_world_worker registered event omitted backend_id")
    })?;
    if backend_id != dispatch_request.target_backend_id {
        anyhow::bail!(
            "protocol error: spawn_world_worker registered backend_id {} did not match requested {}",
            backend_id,
            dispatch_request.target_backend_id,
        );
    }

    let world_id = event.world_id.ok_or_else(|| {
        anyhow::anyhow!("protocol error: spawn_world_worker registered event omitted world_id")
    })?;
    if world_id != dispatch_request.world_id {
        anyhow::bail!(
            "protocol error: spawn_world_worker registered world_id {} did not match requested {}",
            world_id,
            dispatch_request.world_id,
        );
    }

    let world_generation = event.world_generation.ok_or_else(|| {
        anyhow::anyhow!(
            "protocol error: spawn_world_worker registered event omitted world_generation"
        )
    })?;
    if world_generation != dispatch_request.world_generation {
        anyhow::bail!(
            "protocol error: spawn_world_worker registered world_generation {} did not match requested {}",
            world_generation,
            dispatch_request.world_generation,
        );
    }

    if event.parent_participant_id != transport_request.parent_participant_id {
        anyhow::bail!(
            "protocol error: spawn_world_worker registered parent_participant_id {:?} did not match requested {:?}",
            event.parent_participant_id,
            transport_request.parent_participant_id,
        );
    }
    if event.resumed_from_participant_id != transport_request.resumed_from_participant_id {
        anyhow::bail!(
            "protocol error: spawn_world_worker registered resumed_from_participant_id {:?} did not match requested {:?}",
            event.resumed_from_participant_id,
            transport_request.resumed_from_participant_id,
        );
    }

    Ok(SpawnWorldWorkerReceipt {
        participant_id,
        orchestrator_participant_id: transport_request.orchestrator_participant_id.clone(),
        parent_participant_id: event.parent_participant_id,
        resumed_from_participant_id: event.resumed_from_participant_id,
        backend_id,
        world_id,
        world_generation,
        launch_span_id,
    })
}

#[cfg(any(target_os = "linux", target_os = "macos", test))]
fn summarize_run_world_task_result(
    backend_id: &str,
    exit_code: i32,
    saw_registered_event: bool,
) -> String {
    let continuity_suffix = if saw_registered_event {
        "; backend surfaced continuity metadata but the dispatch returned terminally without retained shell state"
    } else {
        ""
    };

    match world_task_terminal_state_from_exit_code(exit_code) {
        WorldTaskTerminalStateV1::Completed => {
            format!("run_world_task completed on backend {backend_id}{continuity_suffix}")
        }
        WorldTaskTerminalStateV1::Cancelled => {
            format!(
                "run_world_task was cancelled on backend {backend_id} (exit status 130){continuity_suffix}"
            )
        }
        WorldTaskTerminalStateV1::Failed => {
            format!(
                "run_world_task failed on backend {backend_id} with exit status {exit_code}{continuity_suffix}"
            )
        }
        WorldTaskTerminalStateV1::NeedsRetainedFollowup => {
            format!(
                "run_world_task on backend {backend_id} requires retained follow-up before it can complete"
            )
        }
    }
}

#[cfg(target_os = "linux")]
fn summarize_spawn_world_worker_result(receipt: &SpawnWorldWorkerReceipt) -> String {
    format!(
        "spawn_world_worker launched retained worker {} on backend {}; launch receipt is authoritative but ongoing steering remains out of scope for this packet",
        receipt.participant_id, receipt.backend_id
    )
}

#[cfg(target_os = "linux")]
async fn request_private_stop_after_transport_registration(
    transport_path: &Path,
) -> Result<PrivateStopOutcome> {
    #[cfg(test)]
    notify_private_stop_transport_retry_event(
        transport_path,
        PrivateStopTransportRetryEvent::InitialAttempt,
    );
    match request_private_stop(transport_path).await {
        Ok(outcome) => Ok(outcome),
        Err(err) if !transport_path.exists() => {
            #[cfg(test)]
            notify_private_stop_transport_retry_event(
                transport_path,
                PrivateStopTransportRetryEvent::RetryWaitStarted,
            );
            let started_at = Instant::now();
            while !transport_path.exists() {
                if started_at.elapsed() >= STOP_WORLD_WORKER_CLOSEOUT_WAIT_TIMEOUT {
                    return Err(err);
                }
                tokio::time::sleep(STOP_WORLD_WORKER_CLOSEOUT_POLL_INTERVAL).await;
            }
            #[cfg(test)]
            notify_private_stop_transport_retry_event(
                transport_path,
                PrivateStopTransportRetryEvent::RetryAttempt,
            );
            request_private_stop(transport_path).await
        }
        Err(err) => Err(err),
    }
}

#[cfg(target_os = "linux")]
async fn request_private_stop_after_transport_registration_for_stop_episode(
    store: &AgentRuntimeStateStore,
    resolved: &crate::execution::agent_runtime::state_store::ResolvedInternalStopWorldDispatchTarget,
    transport_path: &Path,
) -> Result<PrivateStopOutcome> {
    #[cfg(test)]
    notify_private_stop_transport_retry_event(
        transport_path,
        PrivateStopTransportRetryEvent::InitialAttempt,
    );
    let initial_result = request_private_stop(transport_path).await;
    stop_order_probe_log(
        &resolved.session.orchestration_session_id,
        Some(resolved.target_participant.participant_id()),
        "private_stop_transport_initial_result",
        serde_json::json!({
            "caller_participant_id": resolved.caller_participant.participant_id(),
            "target_participant_id": resolved.target_participant.participant_id(),
            "transport_path": transport_path.display().to_string(),
            "transport_path_exists": transport_path.exists(),
            "result": match &initial_result {
                Ok(outcome) => format!("{outcome:?}"),
                Err(_) => "transport_error".to_string(),
            },
            "transport_error_kind": initial_result
                .as_ref()
                .err()
                .and_then(private_stop_transport_error_kind)
                .map(|kind| kind.to_string()),
            "transport_error": initial_result
                .as_ref()
                .err()
                .map(|err| format!("{err:#}")),
        }),
    );
    let retry_available = stop_world_worker_sanctioned_recovery_retry_available(
        store,
        resolved,
        transport_path,
        &initial_result,
    )?;
    stop_order_probe_log(
        &resolved.session.orchestration_session_id,
        Some(resolved.target_participant.participant_id()),
        "private_stop_transport_retry_decision",
        serde_json::json!({
            "retry_available": retry_available,
            "transport_path": transport_path.display().to_string(),
        }),
    );
    if !retry_available {
        return initial_result;
    }
    #[cfg(test)]
    notify_private_stop_transport_retry_event(
        transport_path,
        PrivateStopTransportRetryEvent::RetryWaitStarted,
    );
    let started_at = Instant::now();
    while !exact_target_stop_recovery_retry_ready(store, resolved, transport_path)? {
        if started_at.elapsed() >= STOP_WORLD_WORKER_CLOSEOUT_WAIT_TIMEOUT {
            stop_order_probe_log(
                &resolved.session.orchestration_session_id,
                Some(resolved.target_participant.participant_id()),
                "private_stop_transport_retry_timed_out",
                serde_json::json!({
                    "transport_path": transport_path.display().to_string(),
                    "timeout_ms": STOP_WORLD_WORKER_CLOSEOUT_WAIT_TIMEOUT.as_millis(),
                }),
            );
            return initial_result;
        }
        tokio::time::sleep(STOP_WORLD_WORKER_CLOSEOUT_POLL_INTERVAL).await;
    }
    #[cfg(test)]
    notify_private_stop_transport_retry_event(
        transport_path,
        PrivateStopTransportRetryEvent::RetryAttempt,
    );
    request_private_stop(transport_path).await
}

#[cfg(target_os = "linux")]
fn exact_target_stop_recovery_retry_ready(
    store: &AgentRuntimeStateStore,
    resolved: &crate::execution::agent_runtime::state_store::ResolvedInternalStopWorldDispatchTarget,
    transport_path: &Path,
) -> Result<bool> {
    if !transport_path.exists() {
        return Ok(false);
    }

    let Some(refreshed_resolved) =
        refreshed_sanctioned_stop_world_dispatch_target(store, resolved)?
    else {
        return Ok(false);
    };

    // A republished socket alone is not enough: the bounded retry only unlocks once
    // authoritative owner truth has actually recovered for the same exact retained target.
    Ok(refreshed_resolved.caller_participant.participant_id()
        != resolved.caller_participant.participant_id()
        || refreshed_resolved.session.posture != resolved.session.posture)
}

#[cfg(test)]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum PrivateStopTransportRetryEvent {
    InitialAttempt,
    RetryWaitStarted,
    RetryAttempt,
}

#[cfg(test)]
type PrivateStopTransportRetryHook =
    Arc<dyn Fn(PrivateStopTransportRetryEvent, &Path) + Send + Sync>;

#[cfg(test)]
tokio::task_local! {
    static PRIVATE_STOP_TRANSPORT_RETRY_HOOK: PrivateStopTransportRetryHook;
}

#[cfg(test)]
async fn with_private_stop_transport_retry_hook<T>(
    hook: PrivateStopTransportRetryHook,
    future: impl std::future::Future<Output = T>,
) -> T {
    PRIVATE_STOP_TRANSPORT_RETRY_HOOK.scope(hook, future).await
}

#[cfg(test)]
fn notify_private_stop_transport_retry_event(
    transport_path: &Path,
    event: PrivateStopTransportRetryEvent,
) {
    let _ = PRIVATE_STOP_TRANSPORT_RETRY_HOOK.try_with(|hook| hook(event, transport_path));
}

#[cfg(target_os = "linux")]
async fn rollback_failed_fork_child_launch(
    store: &AgentRuntimeStateStore,
    resolved: &crate::execution::agent_runtime::state_store::ResolvedInternalForkWorldDispatchTarget,
    child_participant_id: &str,
) -> Result<()> {
    let transport_path = private_stop_transport_path(
        store,
        resolved.orchestration_session_id(),
        child_participant_id,
    );
    let transport_result = request_private_stop_after_transport_registration(&transport_path).await;
    let closeout = wait_for_stop_world_worker_closeout(
        store,
        resolved.orchestration_session_id(),
        child_participant_id,
    )
    .await;

    match (transport_result, closeout) {
        (Ok(PrivateStopOutcome::Accepted | PrivateStopOutcome::AlreadyTerminal), Ok(_)) => Ok(()),
        (Ok(PrivateStopOutcome::OwnerUnreachable), Ok(_))
        | (Ok(PrivateStopOutcome::ProtocolError), Ok(_))
        | (Err(_), Ok(_)) => Ok(()),
        (Ok(PrivateStopOutcome::Accepted | PrivateStopOutcome::AlreadyTerminal), Err(err)) => {
            Err(err)
        }
        (Ok(PrivateStopOutcome::OwnerUnreachable), Err(err)) => {
            anyhow::bail!(
                "owner_unreachable: private stop transport for retained fork child {} did not stay reachable until durable rollback closeout completed: {err}",
                child_participant_id
            );
        }
        (Ok(PrivateStopOutcome::ProtocolError), Err(err)) => {
            anyhow::bail!(
                "owner_unreachable: private stop transport for retained fork child {} returned a protocol error before durable rollback closeout completed: {err}",
                child_participant_id
            );
        }
        (Err(connect_err), Err(closeout_err)) => {
            anyhow::bail!(
                "owner_unreachable: failed to deliver rollback stop to retained fork child {} and durable rollback closeout was not observed ({connect_err:#}; {closeout_err})",
                child_participant_id
            );
        }
    }
}

#[cfg(target_os = "linux")]
async fn wait_for_fork_child_durable_publication(
    store: &AgentRuntimeStateStore,
    orchestration_session_id: &str,
    child_participant_id: &str,
) -> Result<()> {
    wait_for_fork_child_durable_publication_with_timeouts(
        store,
        orchestration_session_id,
        child_participant_id,
        FORK_CHILD_REGISTRATION_VISIBILITY_WAIT_TIMEOUT,
        FORK_CHILD_STOP_TRANSPORT_VISIBILITY_WAIT_TIMEOUT,
        FORK_CHILD_REGISTRATION_VISIBILITY_POLL_INTERVAL,
    )
    .await
}

#[cfg(target_os = "linux")]
async fn wait_for_fork_child_durable_publication_with_timeouts(
    store: &AgentRuntimeStateStore,
    orchestration_session_id: &str,
    child_participant_id: &str,
    child_visibility_wait_timeout: Duration,
    stop_transport_visibility_wait_timeout: Duration,
    poll_interval: Duration,
) -> Result<()> {
    let stop_transport_path =
        private_stop_transport_path(store, orchestration_session_id, child_participant_id);
    let started_at = tokio::time::Instant::now();
    let mut child_visible_at = None;

    loop {
        let child_visible = store.load_participant(child_participant_id)?.is_some();
        if child_visible && child_visible_at.is_none() {
            child_visible_at = Some(tokio::time::Instant::now());
        }
        let stop_transport_published = stop_transport_path.exists();
        if child_visible && stop_transport_published {
            return Ok(());
        }

        let child_visibility_timed_out = started_at.elapsed() >= child_visibility_wait_timeout;
        let stop_transport_timed_out = child_visible_at
            .map(|observed_at| observed_at.elapsed() >= stop_transport_visibility_wait_timeout)
            .unwrap_or(false);
        if (!child_visible && child_visibility_timed_out)
            || (child_visible && !stop_transport_published && stop_transport_timed_out)
        {
            let mut missing = Vec::new();
            if !child_visible {
                missing.push("missing_target_participant");
            }
            if !stop_transport_published {
                missing.push("missing_stop_transport");
            }
            anyhow::bail!(
                "missing_fork_child_registration: fork_world_worker child {} was not durably published after authoritative registration ({})",
                child_participant_id,
                missing.join(", ")
            );
        }

        tokio::time::sleep(poll_interval).await;
    }
}

#[cfg(target_os = "linux")]
async fn persist_fork_child_lineage(
    store: &AgentRuntimeStateStore,
    resolved: &crate::execution::agent_runtime::state_store::ResolvedInternalForkWorldDispatchTarget,
    child_participant_id: &str,
) -> Result<crate::execution::agent_runtime::state_store::ResolvedInternalForkWorldDispatchLineage>
{
    let started_at = Instant::now();
    let mut child = loop {
        if let Some(child) = store.load_participant(child_participant_id)? {
            break child;
        }
        if started_at.elapsed() >= FORK_CHILD_REGISTRATION_VISIBILITY_WAIT_TIMEOUT {
            anyhow::bail!(
                "missing_fork_child_registration: fork_world_worker child {} was not persisted after authoritative registration",
                child_participant_id
            );
        }
        tokio::time::sleep(FORK_CHILD_REGISTRATION_VISIBILITY_POLL_INTERVAL).await;
    };
    let source_participant_id = resolved.source_participant.participant_id();
    if child.handle.parent_participant_id.as_deref() != Some(source_participant_id) {
        anyhow::bail!(
            "invalid_fork_lineage: authoritative child {} persisted parent_participant_id {:?} instead of source {}",
            child_participant_id,
            child.handle.parent_participant_id,
            source_participant_id
        );
    }
    child.handle.fork_source_participant_id = Some(source_participant_id.to_string());
    store.persist_participant(&child).with_context(|| {
        format!(
            "failed to persist explicit fork lineage for child {}",
            child_participant_id
        )
    })?;
    resolved.project_child_lineage(&child)
}

