fn summarize_fork_world_worker_result(
    receipt: &SpawnWorldWorkerReceipt,
    source_participant_id: &str,
) -> String {
    format!(
        "fork_world_worker launched retained child {} from source {} on backend {}; launch receipt is authoritative and explicit source-to-child lineage is preserved",
        receipt.participant_id, source_participant_id, receipt.backend_id
    )
}

#[cfg(target_os = "linux")]
fn summarize_continue_world_worker_result(
    request: &transport_api_types::MemberTurnSubmitRequestV1,
    turn_kind: ContinueWorldWorkerTurnKind,
    exit_code: i32,
    surfaced_worker_event: Option<&ContinueWorldWorkerEventV1>,
    fork_bootstrap: Option<&ContinueWorldWorkerForkBootstrapOutcome>,
) -> String {
    if let Some(fork_bootstrap) = fork_bootstrap {
        if exit_code == 0 {
            return format!(
                "continue_world_worker delivered typed fork_command to retained worker {} via the existing member-turn seam and launched retained child {} from source {} via the existing fork bootstrap path; explicit source-to-child lineage is preserved and downstream child completion remains worker-defined",
                request.participant_id,
                fork_bootstrap.child_participant_id,
                fork_bootstrap.source_participant_id,
            );
        }

        return format!(
            "continue_world_worker delivered typed fork_command to retained worker {} via the existing member-turn seam, the source turn exited with status {}, and launched retained child {} from source {} via the existing fork bootstrap path; explicit source-to-child lineage is preserved and downstream child completion remains worker-defined",
            request.participant_id,
            exit_code,
            fork_bootstrap.child_participant_id,
            fork_bootstrap.source_participant_id,
        );
    }

    if turn_kind == ContinueWorldWorkerTurnKind::ProgressAck {
        if exit_code == 0 {
            return format!(
                "continue_world_worker delivered typed progress_ack to retained worker {} via the existing member-turn seam; it acknowledges that the host saw the worker's recent progress, and downstream completion remains worker-defined",
                request.participant_id
            );
        }

        return format!(
            "continue_world_worker delivered typed progress_ack to retained worker {} via the existing member-turn seam, but the turn exited with status {}; it acknowledges that the host saw the worker's recent progress, and downstream completion remains worker-defined",
            request.participant_id, exit_code
        );
    }

    if matches!(
        surfaced_worker_event.map(|event| event.event_class),
        Some(ContinueWorldWorkerEventClassV1::ControlAck)
    ) {
        if exit_code == 0 {
            return format!(
                "continue_world_worker delivered to retained worker {} via the existing member-turn seam; retained worker acknowledged the control_directive, but downstream completion remains worker-defined",
                request.participant_id
            );
        }

        return format!(
            "continue_world_worker delivered to retained worker {} via the existing member-turn seam, surfaced retained worker acknowledgement of the control_directive, but the turn exited with status {}; downstream completion remains worker-defined",
            request.participant_id, exit_code
        );
    }

    if exit_code == 0 {
        format!(
            "continue_world_worker delivered to retained worker {} via the existing member-turn seam; downstream acknowledgement remains worker-defined",
            request.participant_id
        )
    } else {
        format!(
            "continue_world_worker delivered to retained worker {} via the existing member-turn seam, but the turn exited with status {}; downstream acknowledgement remains worker-defined",
            request.participant_id, exit_code
        )
    }
}

