    #[cfg(target_os = "linux")]
    fn b21_test_acceptance_stores() -> (
        TempDir,
        WorldWorkReceiptRegistry,
        WorldWorkExecutionSupervisor,
        String,
    ) {
        use std::os::unix::fs::PermissionsExt as _;

        let safe_parent = std::env::var_os("XDG_RUNTIME_DIR")
            .map(PathBuf::from)
            .unwrap_or_else(|| {
                PathBuf::from(std::env::var_os("HOME").expect("tests require HOME")).join(".cache")
            });
        fs::create_dir_all(&safe_parent).expect("create B2.1 acceptance test parent");
        let root_path =
            tempfile::tempdir_in(safe_parent).expect("create B2.1 acceptance test root");
        fs::set_permissions(root_path.path(), std::fs::Permissions::from_mode(0o700))
            .expect("secure B2.1 acceptance test root");
        let authority = crate::execution::agent_runtime::host_session_authority::facade::HostSessionAuthority::open(root_path.path())
            .expect("open B2.1 acceptance authority");
        let root = authority
            .bootstrap()
            .expect("activate B2.1 acceptance authority");
        let receipt_registry = WorldWorkReceiptRegistry::bind_for_test(
            root_path.path(),
            &root.bootstrap_home,
            &root.authority_store_id,
        )
        .expect("bind B2.1 receipt registry");
        let execution_supervisor = WorldWorkExecutionSupervisor::bind(
            root_path.path(),
            &root.bootstrap_home,
            &root.authority_store_id,
        )
        .expect("bind B2.1 execution supervisor");
        (
            root_path,
            receipt_registry,
            execution_supervisor,
            root.authority_store_id,
        )
    }

    #[cfg(target_os = "linux")]
    fn seed_b21_ephemeral_observation(
        task_run_id: &str,
    ) -> (
        TempDir,
        WorldWorkReceiptRegistry,
        WorldWorkExecutionSupervisor,
        crate::execution::agent_runtime::world_work_execution_supervisor::WorldWorkExecutionClaimV1,
    ) {
        let (root, receipt_registry, execution_supervisor, authority_store_id) =
            b21_test_acceptance_stores();
        let (proposal, request) =
            reserve_b21_task_acceptance(&receipt_registry, &authority_store_id);
        let start = transport_api_types::ExecuteStreamFrame::Start {
            frame_identity: test_runtime_frame_identity(1),
            span_id: task_run_id.to_string(),
        };
        let mut claim = None;
        consume_task_acceptance_acknowledgement(
            &request,
            &proposal,
            Some(&start),
            false,
            |record| {
                let accepted =
                    receipt_registry.persist_world_work_acceptance_for_supervision(record)?;
                claim = Some(execution_supervisor.claim_persisted_world_work(&accepted)?);
                Ok(())
            },
        )
        .expect("persist accepted B2.1 recovery task");
        let claim = claim.expect("B2.1 recovery task has durable claim");
        execution_supervisor
            .journal_frame(
                &claim,
                &start,
                &start
                    .canonical_ndjson_bytes()
                    .expect("canonical B2.1 recovery Start"),
            )
            .expect("journal B2.1 recovery Start");
        (root, receipt_registry, execution_supervisor, claim)
    }

    #[cfg(target_os = "linux")]
    struct BOwnedEphemeralAcceptanceSeed<'a> {
        orchestration_session_id: &'a str,
        caller_participant_id: &'a str,
        caller_backend_id: &'a str,
        target_backend_id: &'a str,
        world_id: &'a str,
        world_generation: u64,
        task_run_id: &'a str,
    }

    #[cfg(target_os = "linux")]
    struct BOwnedEphemeralObservationSeed {
        journal_start: bool,
    }

    #[cfg(target_os = "linux")]
    fn seed_b_owned_ephemeral_acceptance(
        authority: &crate::execution::agent_runtime::state_store::ResolvedWorldWorkRegistryAuthorityV1,
        seed: BOwnedEphemeralAcceptanceSeed<'_>,
    ) -> (
        WorldWorkAcceptanceRecordV1,
        crate::execution::agent_runtime::world_work_execution_supervisor::WorldWorkExecutionClaimV1,
    ) {
        seed_b_owned_ephemeral_acceptance_with_observation(
            authority,
            seed,
            BOwnedEphemeralObservationSeed {
                journal_start: true,
            },
        )
    }

    #[cfg(target_os = "linux")]
    fn seed_b_owned_ephemeral_acceptance_with_observation(
        authority: &crate::execution::agent_runtime::state_store::ResolvedWorldWorkRegistryAuthorityV1,
        seed: BOwnedEphemeralAcceptanceSeed<'_>,
        observation_seed: BOwnedEphemeralObservationSeed,
    ) -> (
        WorldWorkAcceptanceRecordV1,
        crate::execution::agent_runtime::world_work_execution_supervisor::WorldWorkExecutionClaimV1,
    ) {
        let request_id = format!(
            "req-seed-{}-{}",
            seed.orchestration_session_id, seed.task_run_id
        );
        let mut execute_request_out = None;
        let outcome = authority
            .receipt_registry
            .prepare_world_work_acceptance_proposal(
                seed.orchestration_session_id,
                &request_id,
                WorldWorkProposalFamilyV1::EphemeralTask,
                |allocation| {
                    let (mut proposal, mut execute_request) = sample_task_acceptance_submission();
                    let WorldWorkSubmissionIdentityV1::EphemeralTask {
                        validated_dispatch_request,
                        member_dispatch_request,
                        canonical_execute_request_sha256,
                    } = &mut proposal.submission_identity
                    else {
                        unreachable!("ephemeral seed proposal changed family")
                    };
                    validated_dispatch_request.request_id = request_id.clone();
                    validated_dispatch_request.orchestration_session_id =
                        seed.orchestration_session_id.to_string();
                    validated_dispatch_request.caller_participant_id =
                        seed.caller_participant_id.to_string();
                    validated_dispatch_request.target_backend_id =
                        seed.target_backend_id.to_string();
                    validated_dispatch_request.world_id = seed.world_id.to_string();
                    validated_dispatch_request.world_generation = seed.world_generation;
                    member_dispatch_request.orchestration_session_id =
                        seed.orchestration_session_id.to_string();
                    member_dispatch_request.orchestrator_participant_id =
                        seed.caller_participant_id.to_string();
                    member_dispatch_request.backend_id = seed.target_backend_id.to_string();
                    member_dispatch_request.run_id = request_id.clone();
                    member_dispatch_request.world_id = seed.world_id.to_string();
                    member_dispatch_request.world_generation = seed.world_generation;

                    proposal.acceptance_context.proposed_acceptance_record_id =
                        allocation.acceptance_record_id;
                    proposal.acceptance_context.request_id = request_id.clone();
                    proposal.acceptance_context.message_id = allocation.message_id;
                    proposal.acceptance_context.caller_backend_id =
                        seed.caller_backend_id.to_string();
                    proposal.authority_store_id = authority.authority_store_id.clone();
                    proposal.authority_revision_observed = authority.authority_revision_observed;
                    proposal.orchestration_session_id = seed.orchestration_session_id.to_string();
                    proposal.caller_participant_id = seed.caller_participant_id.to_string();
                    proposal.caller_backend_id = seed.caller_backend_id.to_string();
                    proposal.target_backend_id = seed.target_backend_id.to_string();
                    proposal.world_id = seed.world_id.to_string();
                    proposal.world_generation = seed.world_generation;
                    proposal.current_policy_snapshot_ref =
                        authority.current_policy_snapshot_ref.clone();
                    proposal.current_policy_snapshot_hash =
                        authority.current_policy_snapshot_hash.clone();
                    proposal.current_policy_revision = authority.current_policy_revision.clone();
                    proposal.created_at = allocation.created_at;

                    execute_request.member_dispatch = Some(member_dispatch_request.clone());
                    execute_request.acceptance_context = Some(proposal.acceptance_context.clone());
                    *canonical_execute_request_sha256 = canonical_world_work_submission_sha256(
                        validated_dispatch_request,
                        &execute_request,
                    )?;
                    execute_request_out = Some(execute_request);
                    Ok(proposal)
                },
            )
            .expect("reserve B-owned ephemeral acceptance proposal");
        let WorldWorkProposalReservationOutcomeV1::Proposed(proposal) = outcome else {
            panic!("fresh B-owned acceptance seed cannot already be accepted")
        };
        let execute_request = execute_request_out.expect("ephemeral seed returns execute request");
        let start = transport_api_types::ExecuteStreamFrame::Start {
            frame_identity: test_runtime_frame_identity(1),
            span_id: seed.task_run_id.to_string(),
        };
        let mut claim = None;
        consume_task_acceptance_acknowledgement(
            &execute_request,
            &proposal,
            Some(&start),
            false,
            |record| {
                let accepted = authority
                    .receipt_registry
                    .persist_world_work_acceptance_for_supervision(record)?;
                claim = Some(
                    authority
                        .execution_supervisor
                        .claim_persisted_world_work(&accepted)?,
                );
                Ok(())
            },
        )
        .expect("persist B-owned ephemeral acceptance");
        let claim = claim.expect("B-owned acceptance creates supervisor claim");
        if observation_seed.journal_start {
            authority
                .execution_supervisor
                .journal_frame(
                    &claim,
                    &start,
                    &start
                        .canonical_ndjson_bytes()
                        .expect("canonical B-owned Start"),
                )
                .expect("journal B-owned Start");
        }
        let acceptance = authority
            .receipt_registry
            .inspect_world_work_acceptance_by_id(
                &authority.authority_store_id,
                &claim.acceptance_record_id,
            )
            .expect("inspect seeded B-owned acceptance")
            .expect("seeded B-owned acceptance exists");
        (acceptance, claim)
    }

    #[cfg(target_os = "linux")]
    fn reserve_b21_task_acceptance(
        receipt_registry: &WorldWorkReceiptRegistry,
        authority_store_id: &str,
    ) -> (
        WorldWorkAcceptanceProposalV1,
        transport_api_types::ExecuteRequest,
    ) {
        let mut request_out = None;
        let outcome = receipt_registry
            .prepare_world_work_acceptance_proposal(
                "sess_dispatch",
                "req_dispatch",
                WorldWorkProposalFamilyV1::EphemeralTask,
                |allocation| {
                    let (mut proposal, mut request) = sample_task_acceptance_submission();
                    proposal.acceptance_context.proposed_acceptance_record_id =
                        allocation.acceptance_record_id;
                    proposal.acceptance_context.message_id = allocation.message_id;
                    proposal.authority_store_id = authority_store_id.to_string();
                    proposal.created_at = allocation.created_at;
                    request.acceptance_context = Some(proposal.acceptance_context.clone());
                    let WorldWorkSubmissionIdentityV1::EphemeralTask {
                        validated_dispatch_request,
                        canonical_execute_request_sha256,
                        ..
                    } = &mut proposal.submission_identity
                    else {
                        unreachable!("task test proposal changed family")
                    };
                    *canonical_execute_request_sha256 = canonical_world_work_submission_sha256(
                        validated_dispatch_request,
                        &request,
                    )?;
                    request_out = Some(request);
                    Ok(proposal)
                },
            )
            .expect("reserve B2.1 task acceptance proposal");
        let WorldWorkProposalReservationOutcomeV1::Proposed(proposal) = outcome else {
            panic!("fresh B2.1 task proposal cannot already be accepted")
        };
        (
            proposal,
            request_out.expect("B2.1 task proposal builder returns transport request"),
        )
    }

    #[cfg(target_os = "linux")]
    fn reserve_b21_retained_acceptance(
        receipt_registry: &WorldWorkReceiptRegistry,
        authority_store_id: &str,
    ) -> (
        WorldWorkAcceptanceProposalV1,
        transport_api_types::MemberTurnSubmitRequestV1,
    ) {
        reserve_b21_retained_acceptance_with_correlation(receipt_registry, authority_store_id, None)
    }

    #[cfg(target_os = "linux")]
    fn reserve_b21_retained_acceptance_with_correlation(
        receipt_registry: &WorldWorkReceiptRegistry,
        authority_store_id: &str,
        host_transition_correlation: Option<substrate_common::HostTransitionWorkCorrelationV1>,
    ) -> (
        WorldWorkAcceptanceProposalV1,
        transport_api_types::MemberTurnSubmitRequestV1,
    ) {
        let mut request_out = None;
        let outcome = receipt_registry
            .prepare_world_work_acceptance_proposal(
                "sess_dispatch",
                "req_continue",
                WorldWorkProposalFamilyV1::RetainedTurn,
                |allocation| {
                    let (mut proposal, mut request) = sample_retained_acceptance_submission();
                    let message_id = allocation
                        .message_id
                        .expect("retained B2.1 allocation includes message ID");
                    proposal.acceptance_context.proposed_acceptance_record_id =
                        allocation.acceptance_record_id;
                    proposal.acceptance_context.message_id = Some(message_id.clone());
                    proposal.authority_store_id = authority_store_id.to_string();
                    proposal.created_at = allocation.created_at;
                    proposal.acceptance_context.host_transition_correlation =
                        host_transition_correlation.clone();
                    request.acceptance_context = Some(proposal.acceptance_context.clone());
                    let ProposedWorldWorkIdentityV1::RetainedTurn {
                        message_id: proposed_message_id,
                        ..
                    } = &mut proposal.proposed_work
                    else {
                        unreachable!("retained test proposal changed family")
                    };
                    *proposed_message_id = message_id;
                    let WorldWorkSubmissionIdentityV1::RetainedTurn {
                        validated_dispatch_request,
                        canonical_member_turn_submit_request_sha256,
                    } = &mut proposal.submission_identity
                    else {
                        unreachable!("retained test submission changed family")
                    };
                    *canonical_member_turn_submit_request_sha256 =
                        canonical_world_work_submission_sha256(
                            validated_dispatch_request,
                            &request,
                        )?;
                    request_out = Some(request);
                    Ok(proposal)
                },
            )
            .expect("reserve B2.1 retained acceptance proposal");
        let WorldWorkProposalReservationOutcomeV1::Proposed(proposal) = outcome else {
            panic!("fresh B2.1 retained proposal cannot already be accepted")
        };
        (
            proposal,
            request_out.expect("B2.1 retained proposal builder returns transport request"),
        )
    }

    #[cfg(target_os = "linux")]
    async fn wait_for_b21_claim(
        supervisor: &WorldWorkExecutionSupervisor,
        acceptance_record_id: &str,
    ) -> crate::execution::agent_runtime::world_work_execution_supervisor::WorldWorkExecutionClaimV1
    {
        timeout(Duration::from_secs(3), async {
            loop {
                if let Some(claim) = supervisor
                    .inspect_claim_by_acceptance_id(acceptance_record_id)
                    .expect("inspect B2.1 claim")
                {
                    break claim;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("timed out waiting for durable B2.1 claim")
    }

    #[cfg(target_os = "linux")]
    async fn wait_for_b21_terminal(
        supervisor: &WorldWorkExecutionSupervisor,
        acceptance_record_id: &str,
    ) -> crate::execution::agent_runtime::world_work_execution_supervisor::WorldWorkTerminalObservationV1
    {
        timeout(Duration::from_secs(3), async {
            loop {
                if let Some(terminal) = supervisor
                    .inspect_observation_by_acceptance_id(acceptance_record_id)
                    .expect("inspect B2.1 terminal observation")
                    .and_then(|observation| observation.terminal)
                {
                    break terminal;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("timed out waiting for durable B2.1 terminal observation")
    }

