    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    #[serial]
    async fn b1_b21_0_ordinary_continue_joins_canonical_retained_target_and_supervision() {
        let _env_guard = world_env_guard();
        let _world_codex_guard = EnvVarGuard::set_path(
            "SUBSTRATE_WORLD_DEPS_GUEST_BIN_DIR",
            test_world_codex_runtime_bin().as_path(),
        );
        let substrate_home = secure_authority_tempdir();
        substrate_home.install_as_home();
        write_allowed_world_dispatch_policy_with_follow_up_requests(
            substrate_home.path(),
            "cli:codex-world",
            &[
                "spawn_world_worker",
                "continue_world_worker",
                "inspect_world_worker",
            ],
            &["retained", "ephemeral"],
        );
        write_runtime_inventory_entry(
            substrate_home.path(),
            "codex-world",
            AgentExecutionScope::World,
        );
        let workspace_root = tempdir().expect("workspace root tempdir");
        activate_b_owned_dispatch_authority(
            substrate_home.path(),
            workspace_root.path(),
            "sess_dispatch",
            "orch_dispatch",
            "cli:codex",
            "world-17",
            2,
        );
        let store = AgentRuntimeStateStore::new().expect("state store");
        let pre_spawn_authority = store
            .resolve_world_work_registry_authority(
                "sess_dispatch",
                "orch_dispatch",
                "world-17",
                2,
                None,
            )
            .expect("resolve pre-Spawn B-owned authority");
        seed_b_owned_ephemeral_acceptance(
            &pre_spawn_authority,
            BOwnedEphemeralAcceptanceSeed {
                orchestration_session_id: "sess_dispatch",
                caller_participant_id: "orch_dispatch",
                caller_backend_id: "cli:codex",
                target_backend_id: "cli:codex-world",
                world_id: "world-17",
                world_generation: 2,
                task_run_id: "task-run-before-retained-registration",
            },
        );

        let socket_home = tempdir().expect("socket tempdir");
        let socket_path = socket_home.path().join("world.sock");
        let listener = UnixListener::bind(&socket_path).expect("bind world socket");
        let (continue_seen_tx, continue_seen_rx) = tokio::sync::oneshot::channel();
        let fixture_tasks = TestFixtureTaskOwner::new();
        let fixture_tasks_for_server = fixture_tasks.clone();
        let server = tokio::spawn(async move {
            let mut continue_seen_tx = Some(continue_seen_tx);
            while let Ok((mut stream, _addr)) = listener.accept().await {
                let Some((header, body)) = read_http_request(&mut stream).await else {
                    continue;
                };
                let first_line = header.lines().next().unwrap_or("");
                if first_line.starts_with("GET /v1/capabilities ") {
                    write_http_json(
                        &mut stream,
                        "200 OK",
                        r#"{"schema_version":1,"policy_snapshot_v1_supported":true}"#,
                    )
                    .await;
                    continue;
                }
                if first_line.starts_with("POST /v1/execute/stream ") {
                    let execute_request: ExecuteRequest =
                        serde_json::from_slice(&body).expect("decode retained Spawn request");
                    let member_dispatch = execute_request
                        .member_dispatch
                        .expect("Spawn request includes member dispatch");
                    write_http_stream_start(&mut stream).await;
                    write_chunked_frame(
                        &mut stream,
                        &transport_api_types::ExecuteStreamFrame::Start {
                            frame_identity: test_runtime_frame_identity(1),
                            span_id: "spawn-retained-target".to_string(),
                        },
                    )
                    .await;
                    write_chunked_frame(
                        &mut stream,
                        &transport_api_types::ExecuteStreamFrame::Event {
                            frame_identity: test_runtime_frame_identity(2),
                            event: substrate_common::agent_events::AgentEvent {
                                ts: chrono::Utc::now(),
                                kind: AgentEventKind::Registered,
                                data: json!({}),
                                agent_id: execute_request.agent_id,
                                orchestration_session_id: member_dispatch
                                    .orchestration_session_id
                                    .clone(),
                                run_id: member_dispatch.run_id.clone(),
                                parent_run_id: None,
                                participant_id: Some(member_dispatch.participant_id.clone()),
                                parent_participant_id: None,
                                resumed_from_participant_id: None,
                                backend_id: Some(member_dispatch.backend_id.clone()),
                                thread_id: None,
                                role: Some("member".to_string()),
                                world_id: Some(member_dispatch.world_id.clone()),
                                world_generation: Some(member_dispatch.world_generation),
                                cmd_id: None,
                                span_id: Some("spawn-retained-target".to_string()),
                                event_identity: Some(test_runtime_event_identity(1)),
                                worker_event: None,
                                channel: None,
                                identity_tuple: None,
                                placement_posture: None,
                                project: None,
                            },
                        },
                    )
                    .await;
                    let mut close_rx = fixture_tasks_for_server.close_receiver();
                    fixture_tasks_for_server.spawn(async move {
                        wait_for_test_fixture_close(&mut close_rx).await;
                        drop(stream);
                    });
                    continue;
                }
                if first_line.starts_with("POST /v1/member_turn/stream ") {
                    let submitted: transport_api_types::MemberTurnSubmitRequestV1 =
                        serde_json::from_slice(&body).expect("decode ordinary Continue request");
                    let acceptance_record_id = submitted
                        .acceptance_context
                        .as_ref()
                        .expect("ordinary Continue includes acceptance context")
                        .proposed_acceptance_record_id
                        .clone();
                    if let Some(continue_seen_tx) = continue_seen_tx.take() {
                        let _ = continue_seen_tx
                            .send((submitted.participant_id.clone(), acceptance_record_id));
                    }
                    write_http_stream_start(&mut stream).await;
                    write_chunked_frame(
                        &mut stream,
                        &transport_api_types::ExecuteStreamFrame::Start {
                            frame_identity: test_runtime_frame_identity(1),
                            span_id: "continue-retained-target".to_string(),
                        },
                    )
                    .await;
                    let mut worker_event = sample_typed_continue_stream_event_for_request(
                        &submitted,
                        test_runtime_frame_identity(2),
                        test_runtime_event_identity(1),
                        json!({
                            "event_class": "follow_up_question",
                            "payload": {
                                "question": "confirm the retained follow-up"
                            }
                        }),
                    );
                    worker_event.span_id = Some("continue-retained-target".to_string());
                    write_chunked_frame(
                        &mut stream,
                        &transport_api_types::ExecuteStreamFrame::Event {
                            frame_identity: test_runtime_frame_identity(2),
                            event: worker_event,
                        },
                    )
                    .await;
                    let mut terminal = b21_test_exit_frame(
                        "rts_shell_world_dispatch_fixture",
                        "continue-retained-target",
                    );
                    let transport_api_types::ExecuteStreamFrame::Exit {
                        frame_identity,
                        event_identity,
                        terminal_identity,
                        ..
                    } = &mut terminal
                    else {
                        unreachable!("B2.1 ordinary Continue fixture terminal changed shape")
                    };
                    frame_identity.frame_sequence = 3;
                    *event_identity = test_runtime_event_identity(2);
                    *terminal_identity = test_runtime_terminal_identity(2);
                    write_chunked_frame(&mut stream, &terminal).await;
                    finish_chunked_stream(&mut stream).await;
                    break;
                }
                write_http_json(&mut stream, "404 Not Found", r#"{"error":"not_found"}"#).await;
            }
        });
        let _socket_guard = EnvVarGuard::set_path("SUBSTRATE_WORLD_SOCKET", &socket_path);

        let test_outcome = run_test_body_with_fixture_task_cleanup(
            server,
            socket_home,
            &socket_path,
            "ordinary retained continue",
            fixture_tasks,
            async {
        let spawn = dispatch_orchestrator_world_request(
            &store,
            WorldDispatchRequestV1 {
                request_id: Some("req_spawn_for_continue".to_string()),
                idempotency_key: Some("idem_spawn_for_continue".to_string()),
                orchestration_session_id: Some("sess_dispatch".to_string()),
                caller_participant_id: Some("orch_dispatch".to_string()),
                action: WorldDispatchActionV1::SpawnWorldWorker,
                mode: WorldDispatchModeV1::Retained,
                target_backend_id: Some("cli:codex-world".to_string()),
                task_run_id: None,
                target_participant_id: None,
                world_id: Some("world-17".to_string()),
                world_generation: Some(2),
                payload: WorldDispatchPayloadV1::WorkerSpawn(WorkerSpawnPayloadV1 {
                    prompt: "create exact retained target".to_string(),
                }),
            },
        )
        .await
        .expect("Spawn canonical retained target");
        let WorldDispatchOutcomeV1::SpawnWorldWorker(spawn) = spawn else {
            panic!("expected SpawnWorldWorker outcome")
        };
        let post_spawn_authority = store
            .resolve_world_work_registry_authority(
                "sess_dispatch",
                "orch_dispatch",
                "world-17",
                2,
                None,
            )
            .expect("resolve post-Spawn B-owned authority");
        assert!(
            post_spawn_authority.authority_revision_observed
                > pre_spawn_authority.authority_revision_observed,
            "retained registration must advance current HSA revision for stale-receipt proof"
        );
        let stale_revision_err = dispatch_orchestrator_world_request(
            &store,
            sample_ephemeral_inspect_world_dispatch_request(
                "task-run-before-retained-registration",
            ),
        )
        .await
        .expect_err("full dispatcher must reject acceptance from an older HSA revision");
        assert_eq!(
            stale_revision_err.to_string(),
            "stale_linkage: orchestration session sess_dispatch active ephemeral task task-run-before-retained-registration no longer matches current dispatch authority"
        );

        let continue_outcome = dispatch_orchestrator_world_request(
            &store,
            WorldDispatchRequestV1 {
                request_id: Some("req_continue_b_owned".to_string()),
                idempotency_key: Some("idem_continue_b_owned".to_string()),
                orchestration_session_id: Some("sess_dispatch".to_string()),
                caller_participant_id: Some("orch_dispatch".to_string()),
                action: WorldDispatchActionV1::ContinueWorldWorker,
                mode: WorldDispatchModeV1::Retained,
                target_backend_id: Some("cli:codex-world".to_string()),
                task_run_id: None,
                target_participant_id: Some(spawn.participant_id.clone()),
                world_id: Some("world-17".to_string()),
                world_generation: Some(2),
                payload: WorldDispatchPayloadV1::WorkerContinue(WorkerContinuePayloadV1 {
                    prompt: "continue exact retained target".to_string(),
                    thread_id: None,
                }),
            },
        )
        .await
        .expect("ordinary Continue uses canonical retained target");
        let WorldDispatchOutcomeV1::ContinueWorldWorker(continued) = continue_outcome else {
            panic!("expected ContinueWorldWorker outcome")
        };
        assert_eq!(continued.target_participant_id, spawn.participant_id);
        assert_eq!(continued.target_backend_id, "cli:codex-world");
        assert_eq!(continued.world_id, "world-17");
        assert_eq!(continued.world_generation, 2);
        assert_eq!(
            continued
                .worker_event
                .as_ref()
                .map(|event| event.event_class),
            Some(ContinueWorldWorkerEventClassV1::FollowUpQuestion),
            "ordinary B-owned Continue must surface the supervised obligation-bearing event"
        );
        let (transport_participant_id, acceptance_record_id) =
            timeout(Duration::from_secs(3), continue_seen_rx)
                .await
                .expect("timed out waiting for ordinary Continue transport")
                .expect("ordinary Continue transport identity");
        assert_eq!(transport_participant_id, continued.target_participant_id);

        let authority = store
            .resolve_world_work_registry_authority(
                "sess_dispatch",
                "orch_dispatch",
                "world-17",
                2,
                Some((&continued.target_participant_id, "cli:codex-world")),
            )
            .expect("resolve post-Continue B-owned authority");
        let retained_acceptance = authority
            .receipt_registry
            .inspect_world_work_acceptance_by_id(
                &authority.authority_store_id,
                &acceptance_record_id,
            )
            .expect("inspect retained acceptance")
            .expect("retained acceptance exists");
        assert!(matches!(
            retained_acceptance.work_identity,
            AcceptedWorldWorkIdentityV1::RetainedTurn { .. }
        ));
        let observation = authority
            .execution_supervisor
            .inspect_observation_by_acceptance_id(&retained_acceptance.acceptance_record_id)
            .expect("inspect retained supervisor")
            .expect("retained supervisor observation exists");
        assert_eq!(observation.durable_frame_cursor, Some(3));
        assert_eq!(observation.journal.len(), 3);
        assert_eq!(observation.terminal.map(|value| value.exit_code), Some(0));
        assert!(
            !store.canonical_obligations_dir("sess_dispatch").exists(),
            "ordinary B-owned Continue must retain the event in the supervisor journal without invoking the legacy obligation writer"
        );
        assert!(
            !substrate_home
                .path()
                .join("run/agent-hub/sessions/sess_dispatch/active-ephemeral-tasks")
                .exists(),
            "ordinary Continue must not activate the legacy task registry"
        );
            },
        )
        .await;
        test_outcome.finish();
    }

    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "current_thread")]
    #[serial]
    async fn dispatch_contract_cancel_world_work_returns_typed_closeout_after_authoritative_cancel()
    {
        let substrate_home = secure_authority_tempdir();
        substrate_home.install_as_home();
        write_allowed_world_dispatch_policy(
            substrate_home.path(),
            "cli:codex-world",
            &["cancel_world_work"],
            &["retained"],
        );

        let workspace_root = tempdir().expect("workspace root tempdir");
        let store = AgentRuntimeStateStore::new().expect("state store");
        persist_authoritative_continue_dispatch_state(&store, workspace_root.path(), "world-17", 2);
        let session = store
            .load_orchestration_session("sess_dispatch")
            .expect("load orchestration session for cancel setup")
            .expect("authoritative orchestration session for cancel setup");
        let mut active_member = store
            .load_participant("ash_member")
            .expect("load retained worker for cancel setup")
            .expect("retained worker for cancel setup");
        active_member.transition_state(AgentRuntimeSessionState::Running);
        active_member.internal.latest_run_id = Some("run-cancel".to_string());
        crate::execution::agent_runtime::control::persist_runtime_snapshots(
            &store,
            &session,
            &active_member,
        )
        .expect("persist cancelable retained worker");
        let (cancel_tx, mut cancel_rx) =
            crate::execution::agent_runtime::control::private_cancel_request_channel();
        let mut cancel_transport =
            crate::execution::agent_runtime::control::register_private_cancel_transport(
                &store,
                "sess_dispatch",
                "ash_member",
                cancel_tx,
            )
            .await
            .expect("register private cancel transport");
        let store_for_task = store.clone();
        let cancel_owner = tokio::spawn(async move {
            let request = tokio::time::timeout(Duration::from_secs(3), cancel_rx.recv())
                .await
                .expect("timed out waiting for private cancel request")
                .expect("private cancel request");
            assert_eq!(
                request.payload.reason.as_deref(),
                Some("operator requested cancel")
            );
            assert_eq!(request.payload.graceful, Some(true));
            let mut session = store_for_task
                .load_orchestration_session("sess_dispatch")
                .expect("load orchestration session for cancel closeout")
                .expect("authoritative orchestration session for cancel closeout");
            let mut participant = store_for_task
                .load_participant("ash_member")
                .expect("load retained participant for cancel closeout")
                .expect("authoritative retained participant for cancel closeout");
            participant.mark_cancelled_terminal_state();
            participant.touch_heartbeat();
            session.mark_cancelled_terminal();
            crate::execution::agent_runtime::control::persist_runtime_snapshots(
                &store_for_task,
                &session,
                &participant,
            )
            .expect("persist retained cancel closeout");
            let _ = request
                .response_tx
                .send(crate::execution::agent_runtime::control::PrivateCancelOutcome::Accepted);
        });

        let prepared =
            prepare_orchestrator_world_dispatch(&store, sample_cancel_world_dispatch_request())
                .expect("prepare cancel dispatch request");
        let outcome = dispatch_prepared_orchestrator_world_request(prepared)
            .await
            .expect("dispatch prepared cancel request");

        let WorldDispatchOutcomeV1::CancelWorldWork(outcome) = outcome else {
            panic!("expected cancel_world_work outcome envelope");
        };
        assert_eq!(outcome.request_id, "req_cancel");
        assert_eq!(outcome.orchestration_session_id, "sess_dispatch");
        assert_eq!(outcome.action, WorldDispatchActionV1::CancelWorldWork);
        assert_eq!(outcome.mode, WorldDispatchModeV1::Retained);
        assert_eq!(outcome.orchestrator_participant_id, "orch_dispatch");
        assert_eq!(outcome.target_participant_id, "ash_member");
        assert_eq!(outcome.target_backend_id, "cli:codex-world");
        assert_eq!(outcome.world_id, "world-17");
        assert_eq!(outcome.world_generation, 2);
        assert_eq!(outcome.state, CancelWorldWorkTerminalStateV1::Cancelled);
        assert_eq!(
            outcome.closeout.participant_state,
            Some(AgentRuntimeSessionState::Invalidated)
        );
        assert_eq!(
            outcome.closeout.session_state,
            Some(OrchestrationSessionState::Invalidated)
        );
        assert!(
            outcome
                .summary
                .contains("dedicated private owner cancel surface"),
            "summary should stay explicit about the dedicated cancel seam: {}",
            outcome.summary
        );

        let session_after = store
            .load_orchestration_session("sess_dispatch")
            .expect("load orchestration session after cancel")
            .expect("retained orchestration session after cancel");
        assert!(session_after.has_cancelled_terminal_truth());
        assert_eq!(
            session_after.invalidation_reason.as_deref(),
            Some("cancelled")
        );

        let participant_after = store
            .load_participant("ash_member")
            .expect("load retained participant after cancel")
            .expect("retained participant after cancel");
        assert!(participant_after.has_cancelled_terminal_truth());
        assert_eq!(
            participant_after.internal.termination_reason.as_deref(),
            Some("cancelled")
        );

        cancel_owner.await.expect("cancel owner task should join");
        cancel_transport.close().await;
    }

    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "current_thread")]
    #[serial]
    async fn dispatch_contract_cancel_world_work_policy_denials_precede_packet_one_unsupported_stub(
    ) {
        struct DenialCase<'a> {
            enabled: bool,
            allowed_backends: &'a [&'a str],
            allowed_actions: &'a [&'a str],
            allowed_modes: &'a [&'a str],
            expected_denial: &'a str,
        }

        let cases = [
            DenialCase {
                enabled: false,
                allowed_backends: &["cli:codex-world"],
                allowed_actions: &["cancel_world_work"],
                allowed_modes: &["retained"],
                expected_denial: "world_dispatch_disabled:",
            },
            DenialCase {
                enabled: true,
                allowed_backends: &["cli:codex-world"],
                allowed_actions: &["inspect_world_worker"],
                allowed_modes: &["retained"],
                expected_denial: "action_not_allowed:",
            },
            DenialCase {
                enabled: true,
                allowed_backends: &["cli:codex-world"],
                allowed_actions: &["cancel_world_work"],
                allowed_modes: &["ephemeral"],
                expected_denial: "mode_not_allowed:",
            },
            DenialCase {
                enabled: true,
                allowed_backends: &["cli:other_world"],
                allowed_actions: &["cancel_world_work"],
                allowed_modes: &["retained"],
                expected_denial: "backend_not_allowed:",
            },
        ];

        for case in cases {
            let substrate_home = install_secure_substrate_home();
            write_world_dispatch_policy(
                substrate_home.path(),
                case.enabled,
                case.allowed_backends,
                case.allowed_actions,
                case.allowed_modes,
            );

            let workspace_root = tempdir().expect("workspace root tempdir");
            let store = AgentRuntimeStateStore::new().expect("state store");
            persist_authoritative_continue_dispatch_state(
                &store,
                workspace_root.path(),
                "world-17",
                2,
            );

            let mut request = sample_cancel_world_dispatch_request();
            request.target_participant_id = Some("ash_missing".to_string());
            let err = dispatch_orchestrator_world_request(&store, request)
                .await
                .expect_err("steering denial must fail closed before cancel stub");
            let message = err.to_string();

            assert!(
                message.contains(case.expected_denial),
                "expected {} in {message}",
                case.expected_denial
            );
            assert!(
                !message.contains("unsupported_dispatch_action"),
                "steering denial must not collapse into packet 1 unsupported cancel: {message}"
            );
            assert!(
                !message.contains("target_not_in_session:"),
                "steering denial must not leak cancel target resolution truth first: {message}"
            );
        }
    }

    #[cfg(target_os = "linux")]
    #[tokio::test(flavor = "current_thread")]
    #[serial]
    async fn dispatch_contract_cancel_world_work_ephemeral_routes_exact_active_task_over_execute_cancel(
    ) {
        let substrate_home = secure_authority_tempdir();
        substrate_home.install_as_home();
        write_allowed_world_dispatch_policy(
            substrate_home.path(),
            "cli:codex-world",
            &["cancel_world_work"],
            &["ephemeral"],
        );

        let workspace_root = tempdir().expect("workspace root tempdir");
        activate_b_owned_dispatch_authority(
            substrate_home.path(),
            workspace_root.path(),
            "sess_dispatch",
            "orch_dispatch",
            "cli:codex",
            "world-17",
            2,
        );
        let store = AgentRuntimeStateStore::new().expect("state store");
        let authority = store
            .resolve_world_work_registry_authority(
                "sess_dispatch",
                "orch_dispatch",
                "world-17",
                2,
                None,
            )
            .expect("resolve exact cancel fixture authority");
        let (acceptance, claim) = seed_b_owned_ephemeral_acceptance(
            &authority,
            BOwnedEphemeralAcceptanceSeed {
                orchestration_session_id: "sess_dispatch",
                caller_participant_id: "orch_dispatch",
                caller_backend_id: "cli:codex",
                target_backend_id: "cli:codex-world",
                world_id: "world-17",
                world_generation: 2,
                task_run_id: "task-run-cancel-live",
            },
        );

        let socket_home = tempdir().expect("socket tempdir");
        let socket_path = socket_home.path().join("world.sock");
        let listener = UnixListener::bind(&socket_path).expect("bind world socket");
        let (cancel_seen_tx, cancel_seen_rx) = tokio::sync::oneshot::channel();
        let mut cancel_seen_tx = Some(cancel_seen_tx);
        let server = tokio::spawn(async move {
            while let Ok((mut stream, _addr)) = listener.accept().await {
                let Some((header, body)) = read_http_request(&mut stream).await else {
                    continue;
                };
                let first_line = header.lines().next().unwrap_or("");

                if first_line.starts_with("GET /v1/capabilities ") {
                    write_http_json(
                        &mut stream,
                        "200 OK",
                        r#"{"schema_version":1,"policy_snapshot_v1_supported":true}"#,
                    )
                    .await;
                    continue;
                }

                if first_line.starts_with("POST /v1/execute/cancel ") {
                    let parsed: ExecuteCancelRequestV1 =
                        serde_json::from_slice(&body).expect("execute cancel request");
                    assert_eq!(parsed.span_id, "task-run-cancel-live");
                    assert_eq!(parsed.sig, "TERM");
                    let body =
                        serde_json::to_string(&transport_api_types::ExecuteCancelResponseV1 {
                            schema_version: 1,
                            delivered: true,
                        })
                        .expect("serialize execute cancel response");
                    write_http_json(&mut stream, "200 OK", &body).await;
                    if let Some(cancel_seen_tx) = cancel_seen_tx.take() {
                        let _ = cancel_seen_tx.send(());
                    }
                    continue;
                }

                write_http_json(&mut stream, "404 Not Found", r#"{"error":"not_found"}"#).await;
            }
        });
        let _socket_guard = EnvVarGuard::set_path("SUBSTRATE_WORLD_SOCKET", &socket_path);

        let test_tasks = TestTaskRegistry::default();
        let tasks_for_test = test_tasks.clone();
        let test_outcome = run_test_body_with_server_cleanup(
            server,
            socket_home,
            &socket_path,
            "ephemeral cancel route",
            async {
                let prepared = prepare_orchestrator_world_dispatch(
                    &store,
                    sample_ephemeral_cancel_world_dispatch_request("task-run-cancel-live"),
                )
                .expect("prepare active cancel dispatch request");
                let dispatch_task =
                    tasks_for_test.spawn(dispatch_prepared_orchestrator_world_request(prepared));
                tokio::time::timeout(Duration::from_secs(3), cancel_seen_rx)
                    .await
                    .expect("timed out waiting for execute cancel delivery")
                    .expect("execute cancel delivery signal");
                assert!(
                    !dispatch_task.is_finished(),
                    "ephemeral cancel must wait for terminal truth before returning cancelled"
                );
                let terminal = b21_test_cancelled_exit_frame(
                    "rts_shell_world_dispatch_fixture",
                    "task-run-cancel-live",
                );
                authority
                    .execution_supervisor
                    .journal_frame(
                        &claim,
                        &terminal,
                        &terminal
                            .canonical_ndjson_bytes()
                            .expect("canonical cancelled terminal fixture"),
                    )
                    .expect("journal exact cancelled terminal fixture");
                let outcome = dispatch_task
                    .await
                    .expect("dispatch join should succeed")
                    .expect("dispatch prepared active cancel request");

                let WorldDispatchOutcomeV1::CancelWorldWork(outcome) = outcome else {
                    panic!("expected cancel_world_work outcome envelope");
                };
                assert_eq!(outcome.request_id, "req_cancel_ephemeral");
                assert_eq!(outcome.orchestration_session_id, "sess_dispatch");
                assert_eq!(outcome.action, WorldDispatchActionV1::CancelWorldWork);
                assert_eq!(outcome.mode, WorldDispatchModeV1::Ephemeral);
                assert_eq!(outcome.orchestrator_participant_id, "orch_dispatch");
                assert_eq!(outcome.target_participant_id, "task-run-cancel-live");
                assert_eq!(outcome.target_backend_id, "cli:codex-world");
                assert_eq!(outcome.world_id, "world-17");
                assert_eq!(outcome.world_generation, 2);
                assert_eq!(outcome.state, CancelWorldWorkTerminalStateV1::Cancelled);
                assert_eq!(outcome.closeout.participant_state, None);
                assert_eq!(outcome.closeout.session_state, None);
                assert!(
            outcome.summary.contains("/v1/execute/cancel"),
            "ephemeral cancel summary should stay explicit about the execute-cancel seam: {}",
            outcome.summary
        );
                assert!(
                    outcome
                        .summary
                        .contains("without reopening retained worker lifecycle state"),
                    "ephemeral cancel summary should stay explicit about non-retained closeout: {}",
                    outcome.summary
                );
                let adapter_outcome = normalize_cancel_world_work_outcome_v1(&outcome)
                    .expect("normalize ephemeral cancel");
                assert_eq!(
                    adapter_outcome.task_run_id.as_deref(),
                    Some("task-run-cancel-live")
                );
                assert_eq!(adapter_outcome.participant_id, None);
                assert_eq!(adapter_outcome.target_backend_id, "cli:codex-world");
                assert_eq!(
                    authority
                        .receipt_registry
                        .inspect_world_work_acceptance_by_id(
                            &authority.authority_store_id,
                            &acceptance.acceptance_record_id,
                        )
                        .expect("inspect immutable cancel receipt"),
                    Some(acceptance),
                    "terminal closeout must not delete immutable accepted truth"
                );
            },
            move || async move { test_tasks.finish_or_abort_and_wait().await },
        )
        .await;
        drop(_socket_guard);
        drop(authority);
        drop(store);
        drop(workspace_root);
        drop(substrate_home);
        test_outcome.finish();
    }

